import{_ as o,o as a,c as t,a3 as r}from"./chunks/framework.DdpBa4_E.js";const g=JSON.parse('{"title":"元素面板篇 - 颜色选择器","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/15-元素面板篇-颜色选择器.md","filePath":"books/chrome-devtools/15-元素面板篇-颜色选择器.md","lastUpdated":1794316978000}'),s={name:"books/chrome-devtools/15-元素面板篇-颜色选择器.md"};function l(c,e,i,d,n,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="元素面板篇-颜色选择器" tabindex="-1">元素面板篇 - 颜色选择器 <a class="header-anchor" href="#元素面板篇-颜色选择器" aria-label="Permalink to &quot;元素面板篇 - 颜色选择器&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>如果你从来没有仔细的查看过颜色选择器，很正常，因为它确实毫不起眼：只有一些可以让我们选择的颜色。但仔细查看你会发现：<code>DevTools</code> 的开发团队在这个小玩意里面放了多到你想象不到信息。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/12/167a1d2cc62a8d0f~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_1-只选择你正在用的颜色" tabindex="-1">1. 只选择你正在用的颜色 <a class="header-anchor" href="#_1-只选择你正在用的颜色" aria-label="Permalink to &quot;1. 只选择你正在用的颜色&quot;">​</a></h2><p>介绍颜色选择器的一部分：</p><ul><li>切换到一个有色调变化的 <code>Material</code> 调色板</li><li>自定义，可以添加和删除颜色</li><li>从 <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Using_CSS_variables" target="_blank" rel="noreferrer">CSS Variables</a> 中选择一个你当前页面使用的样式表中存在的颜色。</li><li>或者所有你在页面的 <code>CSS</code> 中使用的颜色</li></ul><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/1687495003d24d3b~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-直观的选择你的颜色" tabindex="-1">2. 直观的选择你的颜色 <a class="header-anchor" href="#_2-直观的选择你的颜色" aria-label="Permalink to &quot;2. 直观的选择你的颜色&quot;">​</a></h2><p>打开一个文本的调色选择器(是 <code>color</code> 属性， 而不是 <code>background-color</code>) 你会看到 <code>“Contrast ratio(对比度)”</code> 部分。它显示了 <strong>文本的颜色</strong> 与 <strong>开发者工具认为这段文本应该有的背景颜色</strong> 之间的对比度。如果这个数值很高，那么你的文本相对于背景来说，更显而易见，但如果这个值接近 <code>1</code> ，那么文本的颜色几乎不能从背景色中区分。</p><ul><li><p>在数字边上的 “🚫” 意味着对比度太低了。</p></li><li><p>一个 “✅” 意味着这个颜色遵从 <a href="https://www.w3.org/TR/UNDERSTANDING-WCAG20/conformance.html" target="_blank" rel="noreferrer">Web Content Accessibility Guidelines (WCAG) 2.0</a> 的 <strong>AA</strong> 声明，这意味着对比值至少为 <code>3</code>，</p></li><li><p>“✅ ✅” 意味着满足了 <strong>AAA</strong> 声明。</p></li></ul><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/12/167a1d2cc3b22cdd~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>另外，你可以通过点击上文提到的 <code>AA</code> ， <code>AAA</code> 或者 <code>🚫</code> 符号来阅读更多关于<a href="https://developers.google.com/web/fundamentals/accessibility/accessible-styles#color_and_contrast" target="_blank" rel="noreferrer">accessibility rules</a> 中颜色的说明。</p><p>如果你继续探索 <code>对比度</code> 的部分，还可以看到更多的信息，甚至可以选择一个不同的颜色作为背景颜色进行对比，对应的 <code>color spectrum(色谱)</code> 部分现在会显示一个对比的边界线：如果你的背景颜色比这条线上面的颜色更深，代表兼容 <strong><code>AA</code></strong> ，如果背景颜色比这条线上面的更亮，你需要在这条线的下面选择一个颜色。</p>',14)])])}const m=o(s,[["render",l]]);export{g as __pageData,m as default};
